import{_ as t,a0 as o,w as d,s as r,ao as l,I as n,x as a,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 LVM 為你的 Fedora 系統添加存儲 | LCTT x X-CMD","titleTemplate":false,"description":"使用 LVM 為你的 Fedora 系統添加存儲 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LVM 為你的 Fedora 系統添加存儲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LVM 為你的 Fedora 系統添加存儲 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201207 Add storage to your Fedora system with LVM","title":"使用 LVM 為你的 Fedora 系統添加存儲","tag":"202012","desc":""},"relativePath":"202012/20201207 Add storage to your Fedora system with LVM.md","filePath":"[post].md"}'),c={name:"202012/20201207 Add storage to your Fedora system with LVM.md"};function g(u,s,h,b,k,f){const e=o("Link");return d(),r("div",null,[s[29]||(s[29]=l('<h1 id="使用-lvm-為你的-fedora-系統添加存儲" tabindex="-1">使用 LVM 為你的 Fedora 系統添加存儲 <a class="header-anchor" href="#使用-lvm-為你的-fedora-系統添加存儲" aria-label="Permalink to “使用 LVM 為你的 Fedora 系統添加存儲”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/11/lvm-add-disk-816x345.jpg" alt=""></p><p>有時需要在系統中添加另一塊磁盤。這就是<ruby>邏輯卷管理<rt>Logical Volume Management</rt></ruby>（LVM）的用武之地。LVM 的好處之處在於它相當靈活。有幾種方法可以添加一塊磁盤。這篇文章介紹了一種方法。</p><h3 id="注意" tabindex="-1">注意！ <a class="header-anchor" href="#注意" aria-label="Permalink to “注意！”">​</a></h3><p>這篇文章並不包括將新的磁盤物理地安裝到系統中的過程。請查閲你的系統和磁盤文檔，瞭解如何正確地進行安裝。</p><p><strong>重要：</strong> 一定要確保你已經備份重要數據。如果新磁盤已有數據，那麼本文中描述的步驟將破壞數據。</p><h3 id="最好了解" tabindex="-1">最好了解 <a class="header-anchor" href="#最好了解" aria-label="Permalink to “最好了解”">​</a></h3>',7)),n("p",null,[s[1]||(s[1]=a("本文並沒有深入介紹 LVM 的每一個功能，重點是添加磁盤。但基本上你要了解，LVM 有",-1)),s[2]||(s[2]=n("ruby",null,[a("卷組"),n("rt",null,"volume group")],-1)),s[3]||(s[3]=a("（VG），它由一個或多個分區和/或磁盤組成。你把這些分區或磁盤以",-1)),s[4]||(s[4]=n("ruby",null,[a("物理卷"),n("rt",null,"physical volume")],-1)),s[5]||(s[5]=a("（PV）的方式添加到卷組。一個卷組可以分成許多",-1)),s[6]||(s[6]=n("ruby",null,[a("邏輯卷"),n("rt",null,"logical volume")],-1)),s[7]||(s[7]=a("（LV）。邏輯卷可以作為文件系統、ramdisk 等其他存儲使用。更多信息可以在",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Logical_Volume_Manager_(Linux)"},{default:p(()=>[...s[0]||(s[0]=[a("這裏",-1)])]),_:1}),s[8]||(s[8]=a("中找到。",-1))]),s[30]||(s[30]=l(`<p>可以看作是，把物理卷形成一個存儲池（一個卷組），然後從這個存儲池中劃分出邏輯卷，供你的系統直接使用。</p><h3 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h3><p>確保你能看到你要添加的磁盤。在添加磁盤之前使用 <code>lsblk</code> 查看哪些存儲空間已經可用或正在使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk</span></span>
<span class="line"><span>NAME                   MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>zram0                  251:0    0  989M  0 disk [SWAP]</span></span>
<span class="line"><span>vda                    252:0    0   20G  0 disk</span></span>
<span class="line"><span>├─vda1                 252:1    0    1G  0 part /boot</span></span>
<span class="line"><span>└─vda2                 252:2    0   19G  0 part</span></span>
<span class="line"><span>└─fedora_fedora-root   253:0    0   19G  0 lvm  /</span></span></code></pre></div><p>本文使用的是帶有虛擬存儲的虛擬機，因此設備名稱以 <code>vda</code> 開頭代表第一個磁盤，<code>vdb</code> 代表第二個磁盤，以此類推。你的設備名稱可能不同。許多系統會將 <code>sda</code> 作為第一個物理磁盤，<code>sdb</code> 代表第二個磁盤，以此類推。</p><p>當已連接新磁盤，並且你的系統已備份且正在運行，再次使用 <code>lsblk</code> 來查看新的塊設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk</span></span>
<span class="line"><span>NAME                   MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>zram0                  251:0    0  989M  0 disk [SWAP]</span></span>
<span class="line"><span>vda                    252:0    0   20G  0 disk</span></span>
<span class="line"><span>├─vda1                 252:1    0    1G  0 part /boot</span></span>
<span class="line"><span>└─vda2                 252:2    0   19G  0 part</span></span>
<span class="line"><span>└─fedora_fedora-root 253:0    0   19G  0 lvm  /</span></span>
<span class="line"><span>vdb                    252:16   0   10G  0 disk</span></span></code></pre></div><p>現在有一個名為 <code>vdb</code> 的新設備。該設備的位置是 <code>/dev/vdb</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /dev/vdb</span></span>
<span class="line"><span>brw-rw----. 1 root disk 252, 16 Nov 24 12:56 /dev/vdb</span></span></code></pre></div>`,9)),n("p",null,[s[10]||(s[10]=a("我們可以看到磁盤，但我們還不能用 LVM 來使用它。如果你運行 ",-1)),s[11]||(s[11]=n("code",null,"blkid",-1)),s[12]||(s[12]=a("，你應該不會看到它被列出。對於這個和之後的命令，你需要確保你的系統",-1)),i(e,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:p(()=>[...s[9]||(s[9]=[a("已配置好，這樣你可以使用 sudo",-1)])]),_:1}),s[13]||(s[13]=a("：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo blkid</span></span>
<span class="line"><span>/dev/vda1: UUID=&quot;4847cb4d-6666-47e3-9e3b-12d83b2d2448&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;830679b8-01&quot;</span></span>
<span class="line"><span>/dev/vda2: UUID=&quot;k5eWpP-6MXw-foh5-Vbgg-JMZ1-VEf9-ARaGNd&quot; TYPE=&quot;LVM2_member&quot; PARTUUID=&quot;830679b8-02&quot;</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root: UUID=&quot;f8ab802f-8c5f-4766-af33-90e78573f3cc&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot;</span></span>
<span class="line"><span>/dev/zram0: UUID=&quot;fc6d7a48-2bd5-4066-9bcf-f062b61f6a60&quot; TYPE=&quot;swap&quot;</span></span></code></pre></div><h3 id="將磁盤添加到-lvm-中" tabindex="-1">將磁盤添加到 LVM 中 <a class="header-anchor" href="#將磁盤添加到-lvm-中" aria-label="Permalink to “將磁盤添加到 LVM 中”">​</a></h3><p>使用 <code>pvcreate</code> 初始化磁盤。你需要傳遞設備的完整路徑。在這個例子中，它是 <code>/dev/vdb</code>。在你的系統中，它可能是 <code>/dev/sdb</code> 或其他設備名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvcreate /dev/vdb</span></span>
<span class="line"><span>Physical volume &quot;/dev/vdb&quot; successfully created.</span></span></code></pre></div><p>當你運行 <code>blkid</code> 時，你應該看到磁盤已經被初始化為一個 <code>LVM2_member</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo blkid</span></span>
<span class="line"><span>/dev/vda1: UUID=&quot;4847cb4d-6666-47e3-9e3b-12d83b2d2448&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;830679b8-01&quot;</span></span>
<span class="line"><span>/dev/vda2: UUID=&quot;k5eWpP-6MXw-foh5-Vbgg-JMZ1-VEf9-ARaGNd&quot; TYPE=&quot;LVM2_member&quot; PARTUUID=&quot;830679b8-02&quot;</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root: UUID=&quot;f8ab802f-8c5f-4766-af33-90e78573f3cc&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot;</span></span>
<span class="line"><span>/dev/zram0: UUID=&quot;fc6d7a48-2bd5-4066-9bcf-f062b61f6a60&quot; TYPE=&quot;swap&quot;</span></span>
<span class="line"><span>/dev/vdb: UUID=&quot;4uUUuI-lMQY-WyS5-lo0W-lqjW-Qvqw-RqeroE&quot; TYPE=&quot;LVM2_member&quot;</span></span></code></pre></div><p>你可以使用 <code>pvs</code> 列出當前所有可用的物理卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs</span></span>
<span class="line"><span>PV         VG            Fmt  Attr PSize   PFree</span></span>
<span class="line"><span>/dev/vda2  fedora_fedora lvm2 a--  &lt;19.00g     0</span></span>
<span class="line"><span>/dev/vdb                 lvm2 ---   10.00g 10.00g</span></span></code></pre></div><p><code>/dev/vdb</code> 被列為一個 PV （物理卷），但還沒有分配到一個 VG （卷組）。</p><h3 id="將物理卷添加到一個卷組" tabindex="-1">將物理卷添加到一個卷組 <a class="header-anchor" href="#將物理卷添加到一個卷組" aria-label="Permalink to “將物理卷添加到一個卷組”">​</a></h3><p>你可以使用 <code>vgs</code> 找到可用的卷組列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs</span></span>
<span class="line"><span>VG            #PV #LV #SN Attr   VSize   VFree</span></span>
<span class="line"><span>fedora_fedora   1   1   0 wz--n- 19.00g    0</span></span></code></pre></div><p>在本例中，只有一個卷組可用。接下來，將物理卷添加到 <code>fedora_fedora</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgextend fedora_fedora /dev/vdb</span></span>
<span class="line"><span>Volume group &quot;fedora_fedora&quot; successfully extended</span></span></code></pre></div><p>你現在應該看到物理卷已被添加到卷組中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs </span></span>
<span class="line"><span>PV        VG            Fmt  Attr PSize   PFree</span></span>
<span class="line"><span>/dev/vda2 fedora_fedora lvm2 a–   &lt;19.00g 0</span></span>
<span class="line"><span>/dev/vdb  fedora_fedora lvm2 a–   &lt;10.00g &lt;10.00g</span></span></code></pre></div><p>看一下卷組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs</span></span>
<span class="line"><span>VG            #PV #LV #SN Attr  VSize  VFree</span></span>
<span class="line"><span>fedora_fedora 2   1   0   wz–n- 28.99g &lt;10.00g</span></span></code></pre></div><p>你也可以獲得具體卷組和物理卷的詳細列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgdisplay fedora_fedora</span></span>
<span class="line"><span>--- Volume group ---</span></span>
<span class="line"><span>VG Name               fedora_fedora</span></span>
<span class="line"><span>System ID</span></span>
<span class="line"><span>Format                lvm2</span></span>
<span class="line"><span>Metadata Areas        2</span></span>
<span class="line"><span>Metadata Sequence No  3</span></span>
<span class="line"><span>VG Access             read/write</span></span>
<span class="line"><span>VG Status             resizable</span></span>
<span class="line"><span>MAX LV                0</span></span>
<span class="line"><span>Cur LV                1</span></span>
<span class="line"><span>Open LV               1</span></span>
<span class="line"><span>Max PV                0</span></span>
<span class="line"><span>Cur PV                2</span></span>
<span class="line"><span>Act PV                2</span></span>
<span class="line"><span>VG Size               28.99 GiB</span></span>
<span class="line"><span>PE Size               4.00 MiB</span></span>
<span class="line"><span>Total PE              7422</span></span>
<span class="line"><span>Alloc PE / Size       4863 / 19.00 GiB</span></span>
<span class="line"><span>Free  PE / Size       2559 / 10.00 GiB</span></span>
<span class="line"><span>VG UUID               C5dL2s-dirA-SQ15-TfQU-T3yt-l83E-oI6pkp</span></span></code></pre></div><p>看下物理卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvdisplay /dev/vdb</span></span>
<span class="line"><span>--- Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/vdb</span></span>
<span class="line"><span>VG Name               fedora_fedora</span></span>
<span class="line"><span>PV Size               10.00 GiB / not usable 4.00 MiB</span></span>
<span class="line"><span>Allocatable           yes</span></span>
<span class="line"><span>PE Size               4.00 MiB</span></span>
<span class="line"><span>Total PE              2559</span></span>
<span class="line"><span>Free PE               2559</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               4uUUuI-lMQY-WyS5-lo0W-lqjW-Qvqw-RqeroE</span></span></code></pre></div><p>現在我們已經添加了磁盤，我們可以為邏輯卷 （LV） 分配空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvs</span></span>
<span class="line"><span>LV VG Attr LSize Pool Origin Data% Meta% Move Log Cpy%Sync Convert</span></span>
<span class="line"><span>root fedora_fedora -wi-ao---- 19.00g</span></span></code></pre></div><p>看一下邏輯卷。下面是詳細的邏輯卷信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvdisplay fedora_fedora/root</span></span>
<span class="line"><span>--- Logical volume ---</span></span>
<span class="line"><span>LV Path                /dev/fedora_fedora/root</span></span>
<span class="line"><span>LV Name                root</span></span>
<span class="line"><span>VG Name                fedora_fedora</span></span>
<span class="line"><span>LV UUID                yqc9cw-AvOw-G1Ni-bCT3-3HAa-qnw3-qUSHGM</span></span>
<span class="line"><span>LV Write Access        read/write</span></span>
<span class="line"><span>LV Creation host, time fedora, 2020-11-24 11:44:36 -0500</span></span>
<span class="line"><span>LV Status              available</span></span>
<span class="line"><span>LV Size                19.00 GiB</span></span>
<span class="line"><span>Current LE             4863</span></span>
<span class="line"><span>Segments               1</span></span>
<span class="line"><span>Allocation             inherit</span></span>
<span class="line"><span>Read ahead sectors     auto</span></span>
<span class="line"><span>- currently set to     256</span></span>
<span class="line"><span>Block device           253:0</span></span></code></pre></div><p>查看根文件系統（<code>/</code>）的大小，並將它與邏輯卷大小進行比較。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   19G  1.4G   17G   8% /</span></span></code></pre></div><p>邏輯卷和文件系統大小都為 19G。讓我們給根邏輯卷（<code>root</code>）增加 5G。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvresize -L +5G fedora_fedora/root</span></span>
<span class="line"><span>Size of logical volume fedora_fedora/root changed from 19.00 GiB (4863 extents) to 24.00 GiB (6143 extents).</span></span>
<span class="line"><span>Logical volume fedora_fedora/root successfully resized.</span></span></code></pre></div><p>我們現在有 24G 的邏輯卷可用。看看根文件系統（<code>/</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   19G  1.4G   17G   8% /</span></span></code></pre></div><p>我們仍然顯示只有 19G 的空閒空間，這是因為邏輯卷與文件系統不一樣。要使用增加到邏輯卷的新空間，請調整文件系統的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo resize2fs /dev/fedora_fedora/root</span></span>
<span class="line"><span>resize2fs 1.45.6 (20-Mar-2020)</span></span>
<span class="line"><span>Filesystem at /dev/fedora_fedora/root is mounted on /; on-line resizing required</span></span>
<span class="line"><span>old_desc_blocks = 3, new_desc_blocks = 3</span></span>
<span class="line"><span>The filesystem on /dev/fedora_fedora/root is now 6290432 (4k) blocks long.</span></span></code></pre></div><p>看看文件系統的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   24G  1.4G   21G   7% /</span></span></code></pre></div><p>正如你所看到的，根文件系統（<code>/</code>）已經佔用了邏輯捲上的所有可用空間，而且不需要重新啓動。</p><p>現在你已經將一個磁盤初始化為物理卷，並使用新的物理卷擴展了卷組。之後，你增加了邏輯卷的大小，並調整了文件系統的大小，以使用邏輯卷的新空間。</p><hr>`,39)),n("p",null,[s[15]||(s[15]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/add-storage-to-your-fedora-system-with-lvm/"},{default:p(()=>[...s[14]||(s[14]=[a("https://fedoramagazine.org/add-storage-to-your-fedora-system-with-lvm/",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/maztaim/"},{default:p(()=>[...s[16]||(s[16]=[a("Tim Bosse",-1)])]),_:1}),s[21]||(s[21]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[17]||(s[17]=[a("lujun9972",-1)])]),_:1}),s[22]||(s[22]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[18]||(s[18]=[a("geekpi",-1)])]),_:1}),s[23]||(s[23]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[26]||(s[26]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[24]||(s[24]=[a("LCTT",-1)])]),_:1}),s[27]||(s[27]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[25]||(s[25]=[a("Linux中國",-1)])]),_:1}),s[28]||(s[28]=a(" 榮譽推出",-1))])])}const V=t(c,[["render",g]]);export{y as __pageData,V as default};
